//! The schemas the binary embeds (omad-ho1p): `src/contract/schemas.json.zst` holds the
//! bytes `Published::generated()` prints, zstd-compressed, and `robot-docs schema` prints
//! them without a schema generator. This test regenerates them from the types and fails
//! when the committed file differs, comparing the decompressed bytes (never the zstd
//! stream, so a zstd release cannot churn the file). [`REGENERATE`] rewrites it.
//!
//! It also holds the binary's way of printing them, a parse and a print through
//! `SchemaDoc`, to the generated bytes: the embedded file read back prints exactly what
//! the generators printed.

use std::collections::BTreeMap;
use std::path::Path;

use omaddons::contract::schema::{EMBEDDED_LEVEL, EMBEDDED_PATH, Published, REGENERATE, SchemaDoc};

/// The variable [`REGENERATE`] sets.
const UPDATE_VAR: &str = "OMADDONS_UPDATE_SCHEMAS";

#[test]
fn embedded_schemas_are_the_generated_ones() {
    let generated = Published::generated();
    let bytes = serde_json::to_vec(&generated).unwrap();
    let embedded = Published::embedded_bytes();
    if embedded.as_deref().ok() == Some(bytes.as_slice()) {
        let read_back = serde_json::to_vec(&Published::embedded().unwrap()).unwrap();
        assert!(
            read_back == bytes,
            "{EMBEDDED_PATH} read back and printed differs from the generated bytes: SchemaDoc no longer prints a schema as schemars does"
        );
        return;
    }
    if std::env::var(UPDATE_VAR).as_deref() == Ok("1") {
        let compressed = zstd::bulk::compress(&bytes, EMBEDDED_LEVEL).unwrap();
        let path = Path::new(env!("CARGO_MANIFEST_DIR")).join(EMBEDDED_PATH);
        std::fs::write(&path, &compressed).unwrap();
        eprintln!(
            "wrote {EMBEDDED_PATH}: {} bytes of schemas in {} bytes; this test binary embedded the old file, so run the suite again",
            bytes.len(),
            compressed.len()
        );
        return;
    }
    let difference = match &embedded {
        Err(error) => format!("it does not decompress: {}", error.message),
        Ok(old) => match serde_json::from_slice::<Published>(old) {
            Err(error) => format!("it does not read: {error}"),
            Ok(old) => first_difference(&old, &generated),
        },
    };
    panic!("{EMBEDDED_PATH} is not what the types generate ({difference}); run {REGENERATE}");
}

/// The first schema that differs, by section and key, in the listing's order.
fn first_difference(old: &Published, new: &Published) -> String {
    let printed = |doc: &SchemaDoc| serde_json::to_string(doc).unwrap();
    if printed(&old.envelope) != printed(&new.envelope) {
        return "envelope differs".to_owned();
    }
    for (section, old, new) in [
        ("events", &old.events, &new.events),
        ("commands", &old.commands, &new.commands),
        ("files", &old.files, &new.files),
    ] {
        let keys = |map: &BTreeMap<String, SchemaDoc>| map.keys().cloned().collect::<Vec<_>>();
        if keys(old) != keys(new) {
            return format!(
                "{section}: embedded {:?}, generated {:?}",
                keys(old),
                keys(new)
            );
        }
        if let Some(key) = new
            .keys()
            .find(|key| printed(&old[*key]) != printed(&new[*key]))
        {
            return format!("{section}[{key:?}] differs");
        }
    }
    "the bytes differ, not any one schema".to_owned()
}
